theorem.content:
\label{thmA}
Let $M$ be a type $\mathrm{III}_1$ factor with separable predual and with trivial bicentralizer. Let $\theta \in \operatorname{Aut}(M)$ be a state preserving automorphism. Then the following conditions are equivalent:
\begin{enumerate}
	\item $\theta$ has infinite order in $\mathrm{Out}(M)$;
	\item there exists $u \in \mathcal U(M)$ such that $\operatorname{Ad}(u)\circ\theta$ is state preserving and ergodic.
\end{enumerate}

ref_dict.thm-case2:
\begin{thm}\label{thm-case2}
Let $M$ be a type ${\rm III_1}$ factor with separable predual, $\varphi\in M_\ast$ a faithful state, and $\alpha\colon \mathbb Z \actson (M,\varphi)$ a state preserving outer action such that $\Gamma_{\mathrm{mod}} = p\mathbb Z$ for some $p\geq 1$.
Then there exists a unitary $u\in \mathcal U(M)$ such that $\alpha^u$ is an ergodic state preserving action.
\end{thm}

