post_theorem_intro_text:
\noindent The proof exploits natural class of background metrics arising from the homogeneous structure on OT-manifolds.  In the case of Inoue surfaces these are known as Tricerri metrics \cite{tricerri1982some}.  In the next theorem we give some refined estimates in the special case of generalized K\"ahler-Ricci flow (GKRF) \cite{GKRF}.  Oeljeklaus-Toma manifolds admit natural classes of generalized K\"ahler structures with split tangent bundle, and for such metrics the GKRF reduces to a scalar parabolic flow of Monge-Amp\`ere type \cite{StreetsSTB}.

\begin{thm} \label{t:mainthm2} For generalized K\"ahler-Ricci flow on an Oeljeklaus-Toma manifold
\begin{enumerate}
\item The scalar potential $\phi$ satisfies
\begin{align*}
    - C \leq \phi \leq C e^{-t}(1 + t).
\end{align*}
\item Assuming there exists a Tricerri-type metric in $[\gw_0]$, we have
\begin{align*}
    - C e^{-t}(1 + t) \leq \phi \leq C e^{-t}(1 + t).
\end{align*}
\item On Inoue surfaces of type $S_M$, the estimate of item (2) holds. In addition:
\begin{align*}
    -C\leq \dot{\phi}\leq C.
\end{align*}
\item On Inoue surfaces of type $S_M$, we have:
\begin{align*}
        \omega(t)\geq C\omega_h(t),
\end{align*}
where $\omega_h(t)$ is the model flow with initial data the Tricerri metric $h$.
\end{enumerate}
\end{thm}

ref_dict.theorem: intro:
\begin{theorem}\label{theorem: intro}
	Consistently from a measurable cardinal, there are two $\sigma$-complete ultrafilters $\mathcal{V}, \mathcal{W}$ such that $\mathcal{V}$ is Lipschitz below $\mathcal{W}$, but $\mathcal{V}$ and $\mathcal{W}$ are Ketonen-incomparable. Furthermore, the same is also consistent with the assumption that the Weak Ultrapower Axiom holds.
\end{theorem}

ref_dict.Theorem: Separating Lipschitz from Keton:
\begin{theorem}\label{Theorem: Separating Lipschitz from Ketonen the Easy way}
	Assume $V= L[U]$, $\kappa$ is the unique measurable cardinal, $\po$ is the forcing notion described above and $G,G^*, U_0,U_1$ are as above. Denote $\vc = U_0$ and $\wc$ the measure derived from $j^{V[G]}_{(U_1)^2}$ using the ordinal $j_U(\kappa)+\kappa$ as a seed. Then $\vc<_{L} \wc$ but $\vc, \wc$ are Ketonen incomparable.
\end{theorem}

ref_dict.thm-main:
\begin{thm} \label{thm-main}
	Let $X$ be a Euclidean  building.  Let $C\subset X$ be a convex subset of $X$
	which is isometric to a convex subset of some Euclidean space.  Then $C$ is contained in an apartment $A$  of $X$.  

	Moreover, if for some $x\in C$ we choose an apartment  $A^x$  in the infinitesimal Euclidean building  $T_xX$ with $T_xC\subset A^x$ then $A$ can be chosen so that $T _xA=A^x$. 
\end{thm}

ref_dict.thm-klsph:
\begin{thm}[Kleiner--Leeb] \label{thm-klsph}
Let $B$ be a spherical building, let $C\subset B$ be a closed, convex, spherical subset. Then there exists an apartment $A\subset B$ which contains $C$.
\end{thm}

ref_dict.rem: non-complete:
\begin{rem} \label{rem: non-complete}
	Here is the only place in this paper, where we discuss non-complete buildings, we refer to  \cite{Parreau}, \cite{Str} for their discussion.
	In any non-complete Euclidean building, Theorem \ref{thm-main} cannot hold as stated. Indeed, any such building $X$ contains a (half-open) geodesic $\gamma:[0,1) \to X$, whose image $C$ is closed as a subset of $X$.  Such $C$ cannot be contained in an apartment. 	However, an extension  of Theorem \ref{thm-main} to non-complete Euclidean buildings and to  
	 $\Lambda$-buildings (cf. \cite{Schwer})  seems possible, we hope to discuss it in a forthcoming work. 
\end{rem}

