\label{thm:main}
	Let $1 \le \ell \le k-1$ be such that $k \ge 3$ and $(k,\ell) \neq (3,1)$, let $t = \floor{\frac{k}{k-\ell}}(k - \ell)$, and let $n$ be sufficiently large and divisible by $k-\ell$.
	Then every $k$-uniform $n$-vertex hypergraph without isolated vertices and having minimum supported co-degree at least $(1 - 1/t)n-(k-3)$ will contain a Hamilton $\ell$-cycle.

ref_dict.thm:Hamilton cycle extremal:
\begin{restatable}{thm}{thmHamiltonCycleExtremal}
		\label{thm:Hamilton cycle extremal}    
		Let $k \ge 3$ and $\ell \in [k-1]$ be such that $(k,\ell) \neq (3,1)$, and set $t = \floor{\frac{k}{k-\ell}}(k-\ell)$.
		Let $1/n\ll \eps \ll 1/k\leq 1/3$ be such that $n$ is divisible by $k-\ell$. 
		Suppose $G$ is an $n$-vertex $k$-graph with no isolated vertices and $\delta^*(G)\geq (1-1/t)n-(k-3)$. If there is a subset $A \subseteq V(G)$ with $|A|=\floor{n/t}$ that contains at most $\eps n^2$ supported pairs, then $G$ has a Hamilton $\ell$-cycle.
	\end{restatable}

