\begin{lemma}\label{lem:eigenvector}
    Let $p=12$. There exist nonnegative weights $(\lambda_s)_{s\in \minsuff}$ with $\lambda_{\varepsilon}>0$ such that for every word $w$ over the alphabet $\mathbb{N}$
    and every $\A\in \binom{\mathbb{N}}{2}$,
    \begin{equation}\label{ineq:eigen}
        \alpha \lambda_{\minsuff(w)} \le \sum_{\substack{ c\in\A\\wc\in \widetilde{\mathcal{C}}^{(p)}}} \lambda_{\minsuff(wc)},
